public class BookStats {
  public static void main(String[] args) {
    int[] pages = {120, 250, 80};
    int total = 0, longBooks = 0;
    for (int count : pages) {
      total += count;
      if (count >= 100) longBooks++;
    }
    System.out.println("total=" + total + " and longBooks=" + longBooks);
  }
}

static int totalPages(int[] pages) {
  java.util.Objects.requireNonNull(pages, "pages");
  int total = 0;
  for (int pageCount : pages) total += pageCount;
  return total;
}

