static <T> java.util.List<T> page(java.util.List<T> values, int offset, int limit) {
  if (offset < 0 || limit < 1) throw new IllegalArgumentException("Invalid page");
  int start = Math.min(offset, values.size());
  int end = start + Math.min(limit, values.size() - start);
  return java.util.List.copyOf(values.subList(start, end));
}

