static java.util.Optional<String> firstUnique(java.util.List<String> values) {
  var counts = new java.util.LinkedHashMap<String, Integer>();
  for (String value : values) counts.merge(value, 1, Integer::sum);
  return counts.entrySet().stream().filter(entry -> entry.getValue() == 1)
      .map(java.util.Map.Entry::getKey).findFirst();
}
